pub fn mpCheckCeilingRemap<'a>(
    ctx: &'a Ctx,
    a0: f64,
    a1: f64,
    a2: f64,
    a3: f64,
    a4: Vec<'a>,
    a5: Val<'a, i32>,
    a6: Val<'a, u32>,
    a7: Vec<'a>,
    a8: i32,
    a9: i32,
) -> i32 {
    // Transliterated from its machine code: calls mpLib_8004ED5C, which reads registers its caller sets without passing them.
    (
        Single(a0),
        Single(a1),
        Single(a2),
        Single(a3),
        a4,
        a5,
        a6,
        a7,
        a8,
        a9,
    )
        .put_regs(ctx);
    asm_mpCheckCeilingRemap(ctx);
    Ret::get(ctx)
}

