    let mut int_x = int_x;
    let mut int_y = int_y;
    let mut a0x = a0x;
    let mut a0y = a0y;
    let mut a1y = a1y;
    let mut b0x = b0x;
    let mut b0y = b0y;
    let mut b1x = b1x;
    let mut b1y = b1y;
